import{_ as n,a0 as d,w as p,s as r,ao as l,I as t,x as s,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"DF-SHOW：一個基於老式 DOS 應用的終端文件管理器 | LCTT x X-CMD","titleTemplate":false,"description":"DF-SHOW：一個基於老式 DOS 應用的終端文件管理器 | LCTT (201908) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"DF-SHOW：一個基於老式 DOS 應用的終端文件管理器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"DF-SHOW：一個基於老式 DOS 應用的終端文件管理器 | LCTT (201908) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201908/20181029 DF-SHOW - A Terminal File Manager Based On An Old DOS Application","title":"DF-SHOW：一個基於老式 DOS 應用的終端文件管理器","tag":"201908","desc":""},"relativePath":"201908/20181029 DF-SHOW - A Terminal File Manager Based On An Old DOS Application.md","filePath":"[post].md"}'),h={name:"201908/20181029 DF-SHOW - A Terminal File Manager Based On An Old DOS Application.md"};function c(g,e,u,f,k,w){const i=d("Link");return p(),r("div",null,[e[20]||(e[20]=l('<h1 id="df-show-一個基於老式-dos-應用的終端文件管理器" tabindex="-1">DF-SHOW：一個基於老式 DOS 應用的終端文件管理器 <a class="header-anchor" href="#df-show-一個基於老式-dos-應用的終端文件管理器" aria-label="Permalink to “DF-SHOW：一個基於老式 DOS 應用的終端文件管理器”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/dfshow-720x340.png" alt=""></p><p>如果你曾經使用過老牌的 MS-DOS，你可能已經使用或聽説過 DF-EDIT。DF-EDIT，意即 <strong>D</strong>irectory <strong>F</strong>ile <strong>Edit</strong>，它是一個鮮為人知的 DOS 文件管理器，最初由 Larry Kroeker 為 MS-DOS 和 PC-DOS 系統而編寫。它用於在 MS-DOS 和 PC-DOS 系統中顯示給定目錄或文件的內容。今天，我偶然發現了一個名為 DF-SHOW 的類似實用程序（<strong>D</strong>irectory <strong>F</strong>ile <strong>Show</strong>），這是一個類 Unix 操作系統的終端文件管理器。它是鮮為人知的 DF-EDIT 文件管理器的 Unix 重寫版本，其基於 1986 年發佈的 DF-EDIT 2.3d。DF-SHOW 完全是自由開源的，並在 GPLv3 下發布。</p><p>DF-SHOW 可以：</p><ul><li>列出目錄的內容，</li><li>查看文件，</li><li>使用你的默認文件編輯器編輯文件，</li><li>將文件複製到不同位置，</li><li>重命名文件，</li><li>刪除文件，</li><li>在 DF-SHOW 界面中創建新目錄，</li><li>更新文件權限，所有者和組，</li><li>搜索與搜索詞匹配的文件，</li><li>啓動可執行文件。</li></ul><h3 id="df-show-用法" tabindex="-1">DF-SHOW 用法 <a class="header-anchor" href="#df-show-用法" aria-label="Permalink to “DF-SHOW 用法”">​</a></h3><p>DF-SHOW 實際上是兩個程序的結合，名為 <code>show</code> 和 <code>sf</code>。</p><h4 id="show-命令" tabindex="-1">Show 命令 <a class="header-anchor" href="#show-命令" aria-label="Permalink to “Show 命令”">​</a></h4><p><code>show</code> 程序（類似於 <code>ls</code> 命令）用於顯示目錄的內容、創建新目錄、重命名和刪除文件/文件夾、更新權限、搜索文件等。</p><p>要查看目錄中的內容列表，請使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ show &lt;directory path&gt;</span></span></code></pre></div><p>示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ show dfshow</span></span></code></pre></div><p>這裏，<code>dfshow</code> 是一個目錄。如果在未指定目錄路徑的情況下調用 <code>show</code> 命令，它將顯示當前目錄的內容。</p><p>這是 DF-SHOW 默認界面的樣子。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/dfshow-1.png" alt=""></p><p>如你所見，DF-SHOW 的界面不言自明。</p><p>在頂部欄上，你會看到可用的選項列表，例如複製、刪除、編輯、修改等。</p><p>完整的可用選項列表如下：</p><ul><li><code>C</code> opy（複製）</li><li><code>D</code> elete（刪除）</li><li><code>E</code> dit（編輯）</li><li><code>H</code> idden（隱藏）</li><li><code>M</code> odify（修改）</li><li><code>Q</code> uit（退出）</li><li><code>R</code> ename（重命名）</li><li><code>S</code> how（顯示）</li><li>h <code>U</code> nt（文件內搜索）</li><li>e <code>X</code> ec（執行）</li><li><code>R</code> un command（運行命令）</li><li><code>E</code> dit file（編輯文件）</li><li><code>H</code> elp（幫助）</li><li><code>M</code> ake dir（創建目錄）</li><li><code>S</code> how dir（顯示目錄）</li></ul><p>在每個選項中，有一個字母以大寫粗體標記。只需按下該字母即可執行相應的操作。例如，要重命名文件，只需按 <code>R</code> 並鍵入新名稱，然後按回車鍵重命名所選項目。</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/dfshow-2.png" alt=""></p><p>要顯示所有選項或取消操作，只需按 <code>ESC</code> 鍵即可。</p><p>此外，你將在 DF-SHOW 界面的底部看到一堆功能鍵，以瀏覽目錄的內容。</p><ul><li><code>UP</code> / <code>DOWN</code> 箭頭或 <code>F1</code> / <code>F2</code> - 上下移動（一次一行），</li><li><code>PgUp</code> / <code>PgDn</code> - 一次移動一頁，</li><li><code>F3</code> / <code>F4</code> - 立即轉到列表的頂部和底部，</li><li><code>F5</code> - 刷新，</li><li><code>F6</code> - 標記/取消標記文件（標記的文件將在它們前面用 <code>*</code> 表示），</li><li><code>F7</code> / <code>F8</code> - 一次性標記/取消標記所有文件，</li><li><code>F9</code> - 按以下順序對列表排序 - 日期和時間、名稱、大小。</li></ul><p>按 <code>h</code> 瞭解有關 <code>show</code> 命令及其選項的更多詳細信息。</p><p>要退出 DF-SHOW，只需按 <code>q</code> 即可。</p><h4 id="sf-命令" tabindex="-1">SF 命令 <a class="header-anchor" href="#sf-命令" aria-label="Permalink to “SF 命令”">​</a></h4><p><code>sf</code> （顯示文件）用於顯示文件的內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sf &lt;file&gt;</span></span></code></pre></div><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/10/dfshow-3.png" alt=""></p><p>按 <code>h</code> 瞭解更多 <code>sf</code> 命令及其選項。要退出，請按 <code>q</code>。</p><p>想試試看？很好，讓我們繼續在 Linux 系統上安裝 DF-SHOW，如下所述。</p><h3 id="安裝-df-show" tabindex="-1">安裝 DF-SHOW <a class="header-anchor" href="#安裝-df-show" aria-label="Permalink to “安裝 DF-SHOW”">​</a></h3>',34)),t("p",null,[e[2]||(e[2]=s("DF-SHOW 在 ",-1)),o(i,{href:"https://aur.archlinux.org/packages/dfshow/"},{default:a(()=>[...e[0]||(e[0]=[s("AUR",-1)])]),_:1}),e[3]||(e[3]=s(" 中可用，因此你可以使用 AUR 程序（如 ",-1)),o(i,{href:"https://www.ostechnix.com/yay-found-yet-another-reliable-aur-helper/"},{default:a(()=>[...e[1]||(e[1]=[s("yay",-1)])]),_:1}),e[4]||(e[4]=s("）在任何基於 Arch 的系統上安裝它。",-1))]),e[21]||(e[21]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ yay -S dfshow</span></span></code></pre></div><p>在 Ubuntu 及其衍生版上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo add-apt-repository ppa:ian-hawdon/dfshow</span></span>
<span class="line"><span>$ sudo apt-get update</span></span>
<span class="line"><span>$ sudo apt-get install dfshow</span></span></code></pre></div><p>在其他 Linux 發行版上，你可以從源代碼編譯和構建它，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ git clone https://github.com/roberthawdon/dfshow</span></span>
<span class="line"><span>$ cd dfshow</span></span>
<span class="line"><span>$ ./bootstrap</span></span>
<span class="line"><span>$ ./configure</span></span>
<span class="line"><span>$ make</span></span>
<span class="line"><span>$ sudo make install</span></span></code></pre></div><p>DF-SHOW 項目的作者只重寫了 DF-EDIT 實用程序的一些應用程序。由於源代碼可以在 GitHub 上免費獲得，因此你可以添加更多功能、改進代碼並提交或修復錯誤（如果有的話）。它仍處於 beta 階段，但功能齊全。</p><p>你有沒試過嗎？如果試過，覺得如何？請在下面的評論部分告訴我們你的體驗。</p><p>不管如何，希望這有用。還有更多好東西。敬請關注！</p><hr>`,9)),t("p",null,[e[6]||(e[6]=s("via: ",-1)),o(i,{href:"https://www.ostechnix.com/df-show-a-terminal-file-manager-based-on-an-old-dos-application/"},{default:a(()=>[...e[5]||(e[5]=[s("https://www.ostechnix.com/df-show-a-terminal-file-manager-based-on-an-old-dos-application/",-1)])]),_:1})]),t("p",null,[e[11]||(e[11]=s("作者：",-1)),o(i,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...e[7]||(e[7]=[s("SK",-1)])]),_:1}),e[12]||(e[12]=s(" 選題：",-1)),o(i,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[8]||(e[8]=[s("lujun9972",-1)])]),_:1}),e[13]||(e[13]=s(" 譯者：",-1)),o(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[9]||(e[9]=[s("wxy",-1)])]),_:1}),e[14]||(e[14]=s(" 校對：",-1)),o(i,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[17]||(e[17]=s("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[15]||(e[15]=[s("LCTT",-1)])]),_:1}),e[18]||(e[18]=s(" 原創編譯，",-1)),o(i,{href:"https://linux.cn/"},{default:a(()=>[...e[16]||(e[16]=[s("Linux中國",-1)])]),_:1}),e[19]||(e[19]=s(" 榮譽推出",-1))])])}const m=n(h,[["render",c]]);export{S as __pageData,m as default};
